/* =========================================
   🎀 甜甜巧克力专属：正文文字 (P标签) 深度美化 
   ========================================= */

/* 1. 基础段落：糖霜浮雕质感与呼吸排版 */
.mes .mes_text p {
    color: var(--text-main) !important; /* 浓情黑巧色 */
    line-height: 1.85 !important; /* 增加呼吸感，像蓬松的蛋糕 */
    letter-spacing: 0.8px !important; /* 舒展的字间距 */
    margin-bottom: 1.2em !important; /* 段落间留出舒适的空隙 */

    /* 核心特效：极微弱的白色高光+浅褐色底阴影，营造出“刻在白巧克力上”的凸起糖霜浮雕感 */
    text-shadow: 
        0px 1px 1px rgba(255, 255, 255, 0.9), 
        0px 2px 3px rgba(92, 58, 33, 0.08) !important;

    transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) !important;
    position: relative;
}

/* 2. 交互特效：鼠标悬浮时的“草莓巧克力微融”效果 */
.mes .mes_text p:hover {
    color: #3D2314 !important; /* 颜色加深，像纯度更高的黑巧 */
    /* 浮现出淡淡的草莓粉色光晕 */
    text-shadow: 
        0px 0px 8px rgba(255, 158, 187, 0.5),
        0px 1px 1px rgba(255, 255, 255, 0.8) !important;
    /* 极其微小的右侧位移，像果冻一样的微弹触感 */
    transform: translateX(2px);
}

/* 3. 强调文字 (粗体)：奶黄夹心高光 */
.mes .mes_text p strong {
    color: #A0522D !important; /* 焦糖色 */
    font-weight: 800 !important;
    /* 用背景渐变做成文字底部的“奶黄荧光笔”划线效果 */
    background-image: linear-gradient(transparent 60%, rgba(255, 215, 0, 0.4) 60%, rgba(255, 215, 0, 0.4) 100%);
    background-repeat: no-repeat;
    background-size: 100% 100%;
    padding: 0 2px;
    border-radius: 2px;
}

/* 4. 动作/心理描写 (斜体)：草莓糖浆渐变 */
.mes .mes_text p em {
    font-family: var(--font-english-script) !important; /* 英文使用可爱手写体 */
    font-style: italic !important;
    /* 文字使用草莓粉到焦糖色的渐变 */
    background: linear-gradient(45deg, #FF9EBB, #D2691E);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    text-shadow: none !important; /* 渐变字去阴影更通透 */
    font-weight: 600;
    padding: 0 2px;
}
